  @Override
  public void run() {
    try {
      final var cycle = start();
      if (cycle == null) {
        return;
      }
      while (checkCycle(cycle, true)) {
        // checkCycle carries the loop's state and reports when to stop.
      }
    } catch (final InterruptedException e) {
      logger.log(INFO, "Exiting epoch service.");
    }
  }
